from sympy import Rational, floor
def R(x):
    x = Rational(x)
    return 0 if (2*x).q == 1 and (2*x) % 2 != 0 else x - floor(x + Rational(1, 2))

def ok(n, m):
    mu = pow(m, -1, 2*n)
    L = Rational(4, n)*sum((-1)**s * s * R(Rational(m*s, 2*n) + Rational(1, 2)) for s in range(1, n))
    Rr = 2*sum((-1)**s * R(Rational(m*s, 2*n) + Rational(1, 2)) for s in range(1, n)) - 2*sum((-1)**s * R(Rational(mu*s, 2*n) + Rational(1, 2)) for s in range(1, n))
    return L == Rr

all(ok(n, m) for n in range(3, 30, 2) for m in range(1, 2*n) if __import__('math').gcd(m, 2*n) == 1)
